<?php
declare(strict_types=1);
require_once __DIR__.'/auth.php'; require_login();
$pdo=db(); $id=(int)($_GET['id']??0);
$st=$pdo->prepare('SELECT * FROM clients WHERE id=? AND deleted_at IS NULL');$st->execute([$id]);$client=$st->fetch();
if(!$client){http_response_code(404);die('Client not found.');}
if(!table_exists($pdo,'client_comments')) redirect('upgrade_phase2.php');
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf(); $comment=post_string('comment');
 if($comment!==''){ $st=$pdo->prepare('INSERT INTO client_comments(client_id,user_id,comment) VALUES(?,?,?)');$st->execute([$id,current_user()['id'],$comment]);activity($pdo,'comment','clients',$id,'Client comment added');flash('success','Comment saved.');}
 redirect('client_profile.php?id='.$id);
}
$msg=flash('success');
$st=$pdo->prepare('SELECT cc.*,TRIM(CONCAT(COALESCE(u.first_name,"")," ",COALESCE(u.last_name,""))) user_name FROM client_comments cc LEFT JOIN users u ON u.id=cc.user_id WHERE cc.client_id=? ORDER BY cc.id DESC');$st->execute([$id]);$comments=$st->fetchAll();
$st=$pdo->prepare('SELECT * FROM businesses WHERE client_id=? ORDER BY id DESC');$st->execute([$id]);$businesses=$st->fetchAll();
$st=$pdo->prepare('SELECT cs.*,s.name service_name FROM client_services cs JOIN services s ON s.id=cs.service_id WHERE cs.client_id=? ORDER BY cs.id DESC');$st->execute([$id]);$services=$st->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Client Profile · SPS CRM</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font-family:Arial;color:#172033}.top{background:#fff;border-bottom:1px solid #e5eaf2;padding:18px 28px;display:flex;justify-content:space-between}.top a{color:#315ee7;text-decoration:none}.wrap{max-width:1100px;margin:auto;padding:28px}.grid{display:grid;grid-template-columns:1.1fr .9fr;gap:16px}.card{background:#fff;border:1px solid #e5eaf2;border-radius:15px;padding:20px;margin-bottom:16px}.muted{color:#6d788a}.item{padding:12px 0;border-bottom:1px solid #edf0f5}.field textarea{width:100%;padding:12px;border:1px solid #d8dfeb;border-radius:9px;min-height:100px}.btn{background:#315ee7;color:#fff;border:0;padding:11px 15px;border-radius:9px;font-weight:bold;margin-top:8px}.success{background:#ebf9f1;color:#176a3c;padding:10px;border-radius:8px;margin-bottom:14px}@media(max-width:780px){.grid{grid-template-columns:1fr}}</style></head><body><header class="top"><strong>SPS CRM · Client Profile</strong><a href="clients.php">← Clients</a></header><main class="wrap"><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><div class="card"><h1><?=e($client['first_name'].' '.$client['last_name'])?></h1><p class="muted"><?=e($client['client_code'])?> · <?=status_badge($client['status'])?></p><p><?=e($client['email']?:'No email')?> · <?=e($client['phone']?:'No phone')?></p></div><div class="grid"><section><div class="card"><h2>Businesses</h2><?php foreach($businesses as $b):?><div class="item"><strong><?=e($b['business_name'])?></strong><div class="muted"><?=e($b['business_type']?:'Business')?></div></div><?php endforeach;?><?php if(!$businesses):?><div class="muted">No businesses linked yet.</div><?php endif;?></div><div class="card"><h2>Services</h2><?php foreach($services as $s):?><div class="item"><strong><?=e($s['service_name'])?></strong><div class="muted"><?=e($s['status'])?></div></div><?php endforeach;?><?php if(!$services):?><div class="muted">No services linked yet.</div><?php endif;?></div></section><section><div class="card"><h2>Add Comment</h2><form method="post"><?=csrf_field()?><div class="field"><textarea name="comment" required placeholder="Write a client/activity note..."></textarea></div><button class="btn">Save Comment</button></form></div><div class="card"><h2>Comments</h2><?php foreach($comments as $x):?><div class="item"><strong><?=e(trim($x['user_name'])?:'System')?></strong><div><?=nl2br(e($x['comment']))?></div><div class="muted"><?=e($x['created_at'])?></div></div><?php endforeach;?><?php if(!$comments):?><div class="muted">No comments yet.</div><?php endif;?></div></section></div></main></body></html>
